ov 1989 2,946,111\nDec 1989 2,975,537\nJan 1990 2,996,900\nFeb 1990 3,025,827\nMar 1990 3,081,893\nApr 1990 3,093,076\nMay 1990 3,127,229\nJune 1990 3,175,461\"\"\"\n\n# Data from 1991 bulletin (page 76) - covers July 1990 to June 1991\ndata_1991 = \"\"\"July 1990 3,200,338\nAug 1990 3,243,281\nSept 1990 3,266,073\nOct 1990 3,307,748\nNov 1990 3,363,205\nDec 1990 3,397,325\nJan 1991 3,443,129\nFeb 1991 3,488,624\nMar 1991 3,491,694\nApr 1991 3,470,530\nMay 1991 3,522,261\nJune 1991 3,562,942\"\"\"\n\n# Data from 1992 bulletin (page 69) - covers July 1991 to June 1992\ndata_1992 = \"\"\"July 1991 3,597,294\nAug 1991 3,636,298\nSept 1991 3,683,054\nOct 1991 3,735,584\nNov 1991 3,766,152\nDec 1991 3,820,403\nJan 1992 3,826,612\nFeb 1992 3,844,741\nMar 1992 3,897,204\nApr 1992 3,907,963\nMay 1992 3,950,469\nJune 1992 4,000,678\"\"\"\n\n# Data from 1993 bulletin (page 73) - covers July 1992 to June 1993\ndata_1993 = \"\"\"July 1992 4,025,949\nAug 1992 4,064,327\nSept 1992 4,082,871\nOct 1992 4,085,732\nNov 1992 4,151,504\nDec 1992 4,195,926\nJan 1993 4,185,886\nFeb 1993 4,216,166\nMar 1993 4,250,287\nApr 1993 4,274,361\nMay 1993 4,316,774\nJune 1993 4,372,677\"\"\"\n\ndef parse_data(data_str):\n    result = {}\n    for line in data_str.strip().split('\\n'):\n        parts = line.split()\n        month_year = ' '.join(parts[:-1])\n        value = parts[-1].replace(',', '')\n        result[month_year] = int(value)\n    return result\n\nall_data = {**parse_data(data_1990), **parse_data(data_1991), **parse_data(data_1992), **parse_data(data_1993)}\nprint(\"All data extracted:\")\nfor k, v in all_data.items():\n    print(f\"  {k}: {v:,}\")\n\n# Now let's organize by fiscal year\n# Fiscal year 1990: July 1989 - June 1990\n# Fiscal year 1991: July 1990 - June 1991  \n# Fiscal year 1992: July 1991 - June 1992\n# Fiscal year 1993: July 1992 - June 1993\n\nfy90_months = ['July 1989', 'Aug 1989', 'Sept 1989', 'Oct 1989', 'Nov 1989', 'Dec 1989',\n               'Jan 1990', 'Feb 1990