 for i in range(n))\n\n# slope and intercept\nb = (n*sum_xy - sum_x*sum_y) / (n*sum_x2 - sum_x*sum_x)\na = (sum_y - b*sum_x) / n\n\nprint(f'\\\\nRegression: y = {a:.2f} + {b:.2f} * x')\n\n# Predict for fiscal year 1995\nfy95 = 1995\ny_pred = a + b * fy95\n\nprint(f'\\\\nProjected sum for FY 1995: {y_pred:.2f}')\nprint(f'Average per month (FY 1995): {y_pred/12:.2f}')\nprint(f'Rounded to nearest whole number: {round(y_pred/12)}')\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
